// Turkish voice lines (class C). Native script, written from the beat in beats-*.js; never translated from English.
// Group: story-hoods-01-10. beatId -> [{ t, j (joke), spk (only when it differs from the beat) }]. No logic.
Object.assign(P.DLG.tr, {
  "H01b": [{ t: "Hat kapalı! Sarı çizginin gerisine geçin! Bilet kontrolü var!", ok: 1 }],
  "H01i1a": [{ t: "Dürümcüden çıktım. Saçım hâlâ döner kokuyor.", ok: 1 }],
  "H01i1b": [{ t: "Afiyet olsun! Bıçağı sıkma.", ok: 1 }],
  "H01i2a": [{ t: "Yürüyenler, koşanlar, kaldırımdan sürünenler. Hepsi işe geç kalmış gibi.", ok: 1 }],
  "H01i3a": [{ t: "Kural bir: kafaya. Kural iki: yine kafaya", ok: 1 }],
  "H01i3b": [{ t: "17 kilometre kaldı. Hesap yapmayı bıraktım.", ok: 1 }],
  "H02b": [{ t: "Herkes bana baksın! Bayrağı takip edin!", ok: 1 }],
  "H02i1a": [{ t: "Galata merdivenleri. Fenerler yanıyor.", ok: 1 }],
  "H02i1b": [{ t: "Son parçam. Sonra sen de git, olur mu?", ok: 1 }],
  "H02i2a": [{ t: "Merdivende tükürükçü bir zombi. Yere asit sıçratıyor. Tesis yönetimi tatilde.", ok: 1 }],
  "H02i3a": [{ t: "Rehber anlatıyor. Bir zombi başını sallıyor.", ok: 1 }],
  "H02i3b": [{ t: "Galata. 1,8 km yol bitti.", ok: 1 }],
  "H03b": [{ t: "Buketi atıyorum! Kim yakalarsa onun!", ok: 1 }],
  "H03i1a": [{ t: "Karaköy. Düğün kafesi kapalı. Pastalar camda.", ok: 1 }],
  "H03i1b": [{ t: "Düğün pastası. Gelin de damat da yok. Bir dilim?", ok: 1 }],
  "H03i2a": [{ t: "Paşa, sokağın kedisi. Ürkmez, sadece bakar.", ok: 1 }],
  "H03i2b": [{ t: "Paşa önden gidiyor. Mahalle onun, biz misafiriz.", ok: 1 }],
  "H03i3a": [{ t: "Dombililer gaz tüplerinin yanında. Biri patlarsa hepsi patlar.", ok: 1 }],
  "H04b": [{ t: "Olta attım! Çekiyorum, çekiyorum!", ok: 1 }],
  "H04i1a": [{ t: "Galata Köprüsü. İki kat: üstte olta ipleri, altta balık lokantaları.", ok: 1 }],
  "H04i2a": [{ t: "Yaklaşma! Ben balık çeviririm, bu iş bana göre değil! ...Isırıldın mı?", ok: 1 }],
  "H04i3a": [{ t: "Sakin abi. Ben insanım. Sen de öyle görünüyorsun.", ok: 1 }],
  "H04i3b": [{ t: "Olta ipleri ayağa dolanıyor.", ok: 1 }],
  "H05b": [{ t: "Zincir hazır! Hepiniz tekneye! Yemek vakti!", ok: 1 }],
  "H05i1a": [{ t: "Eminönü. Baharat çuvalları, tuzlu hava, balık-ekmek tekneleri.", ok: 1 }],
  "H05i2a": [{ t: "Kaptanımın teknesi burada bağlıydı. Tekne yerinde, kaptan yerinde değil.", ok: 1 }],
  "H05i3a": [{ t: "Kaptan dönmüş. Kaan bunu henüz bilmiyor.", ok: 1 }],
  "H05i3b": [{ t: "Kaan, arkana bak! Hayır, sağındaki. Hızlı ol!", ok: 1 }],
  "H05p1": [{ t: "Baharat çuvalları burnumu yakıyor. Ama ne güzel kokuyor!", ok: 1 }],
  "H05p2": [{ t: "Biber bulutu! Gözünü kapat, hemen geçer.", ok: 1 }],
  "H05p3": [{ t: "Hapşu! Çok yaşa diyen yok. Kendime diyorum.", ok: 1 }],
  "H05p4": [{ t: "İskele eğiliyor! Suya kaymadan geçelim.", ok: 1 }],
  "H06b": [{ t: "Bilet yok, giriş yok!", ok: 1 }],
  "H06i1a": [{ t: "Sirkeci. Kocaman saat hâlâ çalışıyor. Ya da çalışıyormuş gibi.", ok: 1 }],
  "H06i2a": [{ t: "Turnikeler kapalı. Bu kapıyı açacak bir şey lazım.", ok: 1 }],
  "H06i3a": [{ t: "Biletçi kapının arkasında. Önünde zombi sırası.", ok: 1 }],
  "H06i3b": [{ t: "Ben o sıraya girmem. Sıra beklemem ki.", ok: 1 }],
  "H06p1": [{ t: "Turnikeler kapalı. Öbür kapıya dolanalım.", ok: 1 }],
  "H06p2": [{ t: "Bagaj arabası! Kapıya sürelim, zombiler geçemez.", ok: 1 }],
  "H06p3": [{ t: "Saat durmuş. Ya da bize durmuş gibi geliyor.", ok: 1 }],
  "H06p4": [{ t: "Sıraya girmişler. Bilet mi bekliyorlar acaba?", ok: 1 }],
  "H07b": [{ t: "Halılar sarılı, içi dolu. Açarsan bedelini ödersin. Peşin, kartla değil!", ok: 1 }],
  "H07i1a": [{ t: "Kapalıçarşı. Kemerlerin altında sıcak lambalar, duvarda kilimler. Pazarlık hâlâ serbest.", ok: 1 }],
  "H07i2a": [{ t: "Kepenkte el yazısı: 'Kapıyı açmayın.' Ünlem yok. Ünlemsiz uyarı her zaman ciddidir.", ok: 1 }],
  "H07i3a": [{ t: "Biri girmiş. Hâlâ içeride olabilir. Ya da bir şey.", ok: 1 }],
  "H07i3b": [{ t: "Tehlike artık sadece zombi değil. Ve bu hiç iyi bir haber değil.", ok: 1 }],
  "H07p1": [{ t: "Kepenkler iniyor! Arkamdan da bir tane indi! Kapalıçarşı'yı gerçekten kapattılar!", ok: 1 }],
  "H07p2": [{ t: "Kilim rulosu iyi siper olur. Arkasına geç. Halıcı görse fiyatı ikiye katlar.", ok: 1 }],
  "H07p3": [{ t: "Tezgâhların arkasında bir şey kıpırdıyor. 'Bakmak bedava' diyecek, biliyorum.", ok: 1 }],
  "H07p4": [{ t: "Gözünü ayırma. Bu labirentte kaybolan çıkamıyor. Turistler hâlâ içeride.", ok: 1 }],
  "H08b": [{ t: "Yem var, yem! Gel, gel! Sen de gel, seni de beslerim!", ok: 1 }],
  "H08i1a": [{ t: "Beyazıt meydanı. Sahaflar, güvercinler ve kapıda 'Bugün kapalı' tabelası.", ok: 1 }],
  "H08i2a": [{ t: "Güvercinler birden kalktı. Bir şey geliyor. Güvercinler haberi hep önce alır.", ok: 1 }],
  "H08i3a": [{ t: "Güvercinci her sabah kuşları beslerdi. Şimdi kuşlar onu bekliyor. Roller değişti.", ok: 1 }],
  "H08p1": [{ t: "Güvercinler yine kalktı. Sürü geliyor. Kuşlar bizden iyi alarm sistemi.", ok: 1 }],
  "H08p2": [{ t: "Kitapçının kapısı aralık. Kim bıraktı? Kıyamette kitap çalan yok herhalde.", ok: 1 }],
  "H08p3": [{ t: "Burada okumuş biri yaşıyormuş. Kitaplar dizili, tozlu, okunmamış. Tam öğrenci evi.", ok: 1 }],
  "H08p4": [{ t: "Güvercinleri ürkütme. Bizi onlar uyarıyor. Bu şehrin en akıllıları onlar.", ok: 1 }],
  "H09b": [{ t: "Sandığı kaldırdım, şimdi seni kaldırırım! Balık taze, sen de tazesin!", ok: 1 }],
  "H09i1a": [{ t: "Kumkapı. Balık sandıkları buzda. Her yerde deniz kokusu, bir de başka bir şey.", ok: 1 }],
  "H09i2a": [{ t: "Burada bir mezeci vardı. Her yaz gelirdim. Hesap hep ağır gelirdi, şimdi bedava. Acı.", ok: 1 }],
  "H09i3a": [{ t: "Bir zombi müzisyen aynı parçayı çalıyor. Bitmiyor. İstek de kabul etmiyor.", ok: 1 }],
  "H09p1": [{ t: "Buzdaki sandıklar gaz çıkarırsa zincirleme patlar. Uzak dur, balık olma.", ok: 1 }],
  "H09p2": [{ t: "Buz eridi, zemin kaygan. Kıyamete patenle giriyorum.", ok: 1 }],
  "H09p3": [{ t: "Müzik hâlâ çalıyor. Şu sesi kesmemiz lazım, yoksa ben zombiye döneceğim.", ok: 1 }],
  "H09p4": [{ t: "Deniz kokuyor. Yolun yarısını geçmiş olabiliriz. Ya da kaybolduk. İkisinden biri.", ok: 1 }],
  "H10b": [{ t: "Hepsi toptan, hepsi benim! Tanesi beş lira, sen bedavasın!", ok: 1 }],
  "H10i1a": [{ t: "Laleli. Vitrinler dolu. Mankenlerin hepsi bize bakıyor, sanki satılık olan biziz.", ok: 1 }],
  "H10i2a": [{ t: "Bunlar zombi mi, manken mi? İkisi de aynı boş bakıyor.", ok: 1 }],
  "H10i2b": [{ t: "Bilmiyorum. Üç metre mesafe bırakalım. Kimse kimseye yapışmasın.", ok: 1 }],
  "H10i3a": [{ t: "Kıpırdadı! Hepsi kıpırdadı! Mankenlerin canlanmasını hiç istememiştim!", ok: 1 }],
  "H10p1": [{ t: "Vitrin ışıkları çok sert. Göz gözü görmüyor. Laleli'de her şey fazla parlak.", ok: 1 }],
  "H10p2": [{ t: "Üç metreden yakın geçersen uyanıyorlar. Mesafe! Yakın temas yasak!", ok: 1 }],
  "H10p3": [{ t: "Kumaş balyalarının arkasına saklanıyorlar. Saklambaç oynuyorlar, kuralsız.", ok: 1 }],
  "H10p4": [{ t: "Hepsi bana bakıyor. Sanki bir şey bekliyorlar. Ben bir şey yapmadım ama.", ok: 1 }],
});
